CREATE DATABASE IF NOT EXISTS brovault_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE brovault_db;
CREATE TABLE IF NOT EXISTS users(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(500) DEFAULT '') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(180) NOT NULL,description TEXT,category_id BIGINT,price DECIMAL(10,2) NOT NULL,original_price DECIMAL(10,2),stock INT NOT NULL DEFAULT 0,image VARCHAR(255),featured TINYINT DEFAULT 0,active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id),CHECK(price>=0),CHECK(stock>=0),INDEX idx_products_category(category_id),INDEX idx_products_active(active)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wishlists(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,product_id BIGINT NOT NULL,UNIQUE KEY uq_wishlist(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS carts(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL UNIQUE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cart_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,cart_id BIGINT NOT NULL,product_id BIGINT NOT NULL,quantity INT NOT NULL DEFAULT 1,recipient VARCHAR(100) DEFAULT '',message VARCHAR(400) DEFAULT '',wrap TINYINT DEFAULT 0,card TINYINT DEFAULT 0,FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id),CHECK(quantity>0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS coupons(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(40) NOT NULL UNIQUE,discount INT NOT NULL DEFAULT 10,active TINYINT DEFAULT 1,expiry DATE NULL,CHECK(discount BETWEEN 1 AND 80)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,total DECIMAL(10,2) NOT NULL,status ENUM('Pending','Confirmed','Processing','Shipped','Delivered','Cancelled') DEFAULT 'Pending',payment VARCHAR(50),checkout_token VARCHAR(64) UNIQUE,address VARCHAR(800) NOT NULL,coupon VARCHAR(40) DEFAULT '',FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_orders_date(created),INDEX idx_orders_status(status),INDEX idx_orders_user(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,product_id BIGINT NULL,product_name VARCHAR(180) NOT NULL,price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,custom VARCHAR(700) DEFAULT '',FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL,CHECK(quantity>0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,product_id BIGINT,delta INT NOT NULL,note VARCHAR(255),created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS status_history(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,status VARCHAR(30),created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
